    payment_method     LowCardinality(String),
    subtotal           Int64,
    shop_discount      Int64,
    platform_discount  Int64,
    shipping_fee       Int64,
    shipping_subsidy   Int64,
    total              Int64,
    ship_to_name       String,
    ship_to_address    String,
    ship_to_province   LowCardinality(String),
    delivery_attempts  Int32,
    confirm_by         Nullable(DateTime64(6, 'UTC')),
    cancel_reason      LowCardinality(Nullable(String)),
    cancelled_by       LowCardinality(Nullable(String)),
    paid_at            Nullable(DateTime64(6, 'UTC')),
    ready_at           Nullable(DateTime64(6, 'UTC')),
    shipped_at         Nullable(DateTime64(6, 'UTC')),
    delivered_at       Nullable(DateTime64(6, 'UTC')),
    completed_at       Nullable(DateTime64(6, 'UTC')),
    cancelled_at       Nullable(DateTime64(6, 'UTC')),
    version            Int32,
    created_at         DateTime64(6, 'UTC'),
    updated_at         DateTime64(6, 'UTC'),
    _v                 UInt64,
    _gone              UInt8
)
ENGINE = ReplacingMergeTree(_v, _gone)
