    multiIf(r.found, CAST(toInt32(JSONExtractInt(r.row, 'quantity')) AS Int32), s.vis, s.quantity, CAST(toInt32(JSONExtractInt(s._before, 'quantity')) AS Int32)) AS quantity,
    multiIf(r.found, CAST(JSONExtractInt(r.row, 'refund_amount') AS Int64), s.vis, s.refund_amount, CAST(JSONExtractInt(s._before, 'refund_amount') AS Int64)) AS refund_amount,
    multiIf(r.found, CAST(JSONExtract(r.row, 'condition', 'Nullable(String)') AS LowCardinality(Nullable(String))), s.vis, s.condition, CAST(JSONExtract(s._before, 'condition', 'Nullable(String)') AS LowCardinality(Nullable(String)))) AS condition,
    multiIf(r.found, CAST(parseDateTime64BestEffort(JSONExtractString(r.row, 'created_at'), 6, 'UTC') AS DateTime64(6, 'UTC')), s.vis, s.created_at, CAST(parseDateTime64BestEffort(JSONExtractString(s._before, 'created_at'), 6, 'UTC') AS DateTime64(6, 'UTC'))) AS created_at,
    multiIf(r.found, CAST(parseDateTime64BestEffort(JSONExtractString(r.row, 'updated_at'), 6, 'UTC') AS DateTime64(6, 'UTC')), s.vis, s.updated_at, CAST(parseDateTime64BestEffort(JSONExtractString(s._before, 'updated_at'), 6, 'UTC') AS DateTime64(6, 'UTC'))) AS updated_at
FROM (SELECT *, true AS present, _tx_id = 0 OR _synced_at < now64(3) - INTERVAL 30 MINUTE OR _tx_id IN (SELECT tx_id FROM visible) AS vis FROM silver.return_items FINAL WHERE id IN (SELECT k FROM snap.dirty WHERE tbl = 'return_items' AND v = {v:UInt64})) AS s
FULL OUTER JOIN (
    SELECT toUUIDOrZero(JSONExtractString(if(op = 'd', before, after), 'id')) AS k, argMin(before, lsn) AS row, true AS found
    FROM bronze.cdc_events
    WHERE source_table = 'return_items' AND event_ts > now64(3) - INTERVAL 35 MINUTE AND tx_id != 0
      AND tx_id NOT IN (SELECT tx_id FROM visible)
    GROUP BY k HAVING k IN (SELECT k FROM snap.dirty WHERE tbl = 'return_items' AND v = {v:UInt64})) AS r ON s.id = r.k
WHERE if(r.found, r.row != 'null', s.present AND (s.vis OR s._before != 'null'))
SETTINGS join_use_nulls = 0;

CREATE TABLE IF NOT EXISTS snap.seller_ledger_entries
(
    id          Int64,
    shop_id     UUID,
    order_id    Nullable(UUID),
    payout_id   Nullable(UUID),
    entry_type  LowCardinality(String),
    amount      Int64,
    created_at  DateTime64(6, 'UTC'),
    _v          UInt64,
    _gone       UInt8
)
ENGINE = ReplacingMergeTree(_v, _gone)
ORDER BY (shop_id, id);

CREATE OR REPLACE VIEW snap.seller_ledger_entries_delta AS
WITH visible AS (SELECT tx_id FROM bronze.cdc_transactions WHERE ingested_at > now64(3) - INTERVAL 90 MINUTE AND kafka_offset < {v:UInt64})
SELECT id, shop_id, order_id, payout_id, entry_type, amount, created_at FROM silver.seller_ledger_entries FINAL
WHERE (_tx_id = 0 OR _synced_at < now64(3) - INTERVAL 30 MINUTE OR _tx_id IN (SELECT tx_id FROM visible)) AND shop_id IN (SELECT k FROM snap.dirty WHERE tbl = 'seller_ledger_entries' AND v = {v:UInt64});

CREATE TABLE IF NOT EXISTS snap.shop_wallets
(
    shop_id     UUID,
    balance     Int64,
    updated_at  DateTime64(6, 'UTC'),
    _v          UInt64,
    _gone       UInt8
)
ENGINE = ReplacingMergeTree(_v, _gone)
ORDER BY (shop_id);

CREATE OR REPLACE VIEW snap.shop_wallets_delta AS
WITH visible AS (SELECT tx_id FROM bronze.cdc_transactions WHERE ingested_at > now64(3) - INTERVAL 90 MINUTE AND kafka_offset < {v:UInt64})
SELECT
    multiIf(r.found, CAST(toUUID(JSONExtractString(r.row, 'shop_id')) AS UUID), s.vis, s.shop_id, CAST(toUUID(JSONExtractString(s._before, 'shop_id')) AS UUID)) AS shop_id,
    multiIf(r.found, CAST(JSONExtractInt(r.row, 'balance') AS Int64), s.vis, s.balance, CAST(JSONExtractInt(s._before, 'balance') AS Int64)) AS balance,
    multiIf(r.found, CAST(parseDateTime64BestEffort(JSONExtractString(r.row, 'updated_at'), 6, 'UTC') AS DateTime64(6, 'UTC')), s.vis, s.updated_at, CAST(parseDateTime64BestEffort(JSONExtractString(s._before, 'updated_at'), 6, 'UTC') AS DateTime64(6, 'UTC'))) AS updated_at
FROM (SELECT *, true AS present, _tx_id = 0 OR _synced_at < now64(3) - INTERVAL 30 MINUTE OR _tx_id IN (SELECT tx_id FROM visible) AS vis FROM silver.shop_wallets FINAL WHERE shop_id IN (SELECT k FROM snap.dirty WHERE tbl = 'shop_wallets' AND v = {v:UInt64})) AS s
FULL OUTER JOIN (
    SELECT toUUIDOrZero(JSONExtractString(if(op = 'd', before, after), 'shop_id')) AS k, argMin(before, lsn) AS row, true AS found
    FROM bronze.cdc_events
    WHERE source_table = 'shop_wallets' AND event_ts > now64(3) - INTERVAL 35 MINUTE AND tx_id != 0
      AND tx_id NOT IN (SELECT tx_id FROM visible)
    GROUP BY k HAVING k IN (SELECT k FROM snap.dirty WHERE tbl = 'shop_wallets' AND v = {v:UInt64})) AS r ON s.shop_id = r.k
WHERE if(r.found, r.row != 'null', s.present AND (s.vis OR s._before != 'null'))
SETTINGS join_use_nulls = 0;

CREATE TABLE IF NOT EXISTS snap.seller_payouts
(
    id          UUID,
    shop_id     UUID,
    amount      Int64,
    status      LowCardinality(String),
    created_at  DateTime64(6, 'UTC'),
    updated_at  DateTime64(6, 'UTC'),
    _v          UInt64,
    _gone       UInt8
)
ENGINE = ReplacingMergeTree(_v, _gone)
ORDER BY (id);

CREATE OR REPLACE VIEW snap.seller_payouts_delta AS
WITH visible AS (SELECT tx_id FROM bronze.cdc_transactions WHERE ingested_at > now64(3) - INTERVAL 90 MINUTE AND kafka_offset < {v:UInt64})
SELECT
    multiIf(r.found, CAST(toUUID(JSONExtractString(r.row, 'id')) AS UUID), s.vis, s.id, CAST(toUUID(JSONExtractString(s._before, 'id')) AS UUID)) AS id,
    multiIf(r.found, CAST(toUUID(JSONExtractString(r.row, 'shop_id')) AS UUID), s.vis, s.shop_id, CAST(toUUID(JSONExtractString(s._before, 'shop_id')) AS UUID)) AS shop_id,
    multiIf(r.found, CAST(JSONExtractInt(r.row, 'amount') AS Int64), s.vis, s.amount, CAST(JSONExtractInt(s._before, 'amount') AS Int64)) AS amount,
    multiIf(r.found, CAST(JSONExtractString(r.row, 'status') AS LowCardinality(String)), s.vis, s.status, CAST(JSONExtractString(s._before, 'status') AS LowCardinality(String))) AS status,
    multiIf(r.found, CAST(parseDateTime64BestEffort(JSONExtractString(r.row, 'created_at'), 6, 'UTC') AS DateTime64(6, 'UTC')), s.vis, s.created_at, CAST(parseDateTime64BestEffort(JSONExtractString(s._before, 'created_at'), 6, 'UTC') AS DateTime64(6, 'UTC'))) AS created_at,
    multiIf(r.found, CAST(parseDateTime64BestEffort(JSONExtractString(r.row, 'updated_at'), 6, 'UTC') AS DateTime64(6, 'UTC')), s.vis, s.updated_at, CAST(parseDateTime64BestEffort(JSONExtractString(s._before, 'updated_at'), 6, 'UTC') AS DateTime64(6, 'UTC'))) AS updated_at
FROM (SELECT *, true AS present, _tx_id = 0 OR _synced_at < now64(3) - INTERVAL 30 MINUTE OR _tx_id IN (SELECT tx_id FROM visible) AS vis FROM silver.seller_payouts FINAL WHERE id IN (SELECT k FROM snap.dirty WHERE tbl = 'seller_payouts' AND v = {v:UInt64})) AS s
FULL OUTER JOIN (
    SELECT toUUIDOrZero(JSONExtractString(if(op = 'd', before, after), 'id')) AS k, argMin(before, lsn) AS row, true AS found
    FROM bronze.cdc_events
    WHERE source_table = 'seller_payouts' AND event_ts > now64(3) - INTERVAL 35 MINUTE AND tx_id != 0
      AND tx_id NOT IN (SELECT tx_id FROM visible)
    GROUP BY k HAVING k IN (SELECT k FROM snap.dirty WHERE tbl = 'seller_payouts' AND v = {v:UInt64})) AS r ON s.id = r.k
WHERE if(r.found, r.row != 'null', s.present AND (s.vis OR s._before != 'null'))
SETTINGS join_use_nulls = 0;

CREATE TABLE IF NOT EXISTS snap.product_reviews
(
    id             UUID,
    order_item_id  UUID,
    order_id       UUID,
    product_id     UUID,
    shop_id        UUID,
    customer_id    UUID,
    rating         Int32,
    comment        Nullable(String),
    created_at     DateTime64(6, 'UTC'),
    updated_at     DateTime64(6, 'UTC'),
    _v             UInt64,
    _gone          UInt8
)
ENGINE = ReplacingMergeTree(_v, _gone)
ORDER BY (id);

CREATE OR REPLACE VIEW snap.product_reviews_delta AS
WITH visible AS (SELECT tx_id FROM bronze.cdc_transactions WHERE ingested_at > now64(3) - INTERVAL 90 MINUTE AND kafka_offset < {v:UInt64})
SELECT
    multiIf(r.found, CAST(toUUID(JSONExtractString(r.row, 'id')) AS UUID), s.vis, s.id, CAST(toUUID(JSONExtractString(s._before, 'id')) AS UUID)) AS id,
    multiIf(r.found, CAST(toUUID(JSONExtractString(r.row, 'order_item_id')) AS UUID), s.vis, s.order_item_id, CAST(toUUID(JSONExtractString(s._before, 'order_item_id')) AS UUID)) AS order_item_id,
    multiIf(r.found, CAST(toUUID(JSONExtractString(r.row, 'order_id')) AS UUID), s.vis, s.order_id, CAST(toUUID(JSONExtractString(s._before, 'order_id')) AS UUID)) AS order_id,
    multiIf(r.found, CAST(toUUID(JSONExtractString(r.row, 'product_id')) AS UUID), s.vis, s.product_id, CAST(toUUID(JSONExtractString(s._before, 'product_id')) AS UUID)) AS product_id,
    multiIf(r.found, CAST(toUUID(JSONExtractString(r.row, 'shop_id')) AS UUID), s.vis, s.shop_id, CAST(toUUID(JSONExtractString(s._before, 'shop_id')) AS UUID)) AS shop_id,
    multiIf(r.found, CAST(toUUID(JSONExtractString(r.row, 'customer_id')) AS UUID), s.vis, s.customer_id, CAST(toUUID(JSONExtractString(s._before, 'customer_id')) AS UUID)) AS customer_id,
    multiIf(r.found, CAST(toInt32(JSONExtractInt(r.row, 'rating')) AS Int32), s.vis, s.rating, CAST(toInt32(JSONExtractInt(s._before, 'rating')) AS Int32)) AS rating,
    multiIf(r.found, CAST(JSONExtract(r.row, 'comment', 'Nullable(String)') AS Nullable(String)), s.vis, s.comment, CAST(JSONExtract(s._before, 'comment', 'Nullable(String)') AS Nullable(String))) AS comment,
    multiIf(r.found, CAST(parseDateTime64BestEffort(JSONExtractString(r.row, 'created_at'), 6, 'UTC') AS DateTime64(6, 'UTC')), s.vis, s.created_at, CAST(parseDateTime64BestEffort(JSONExtractString(s._before, 'created_at'), 6, 'UTC') AS DateTime64(6, 'UTC'))) AS created_at,
    multiIf(r.found, CAST(parseDateTime64BestEffort(JSONExtractString(r.row, 'updated_at'), 6, 'UTC') AS DateTime64(6, 'UTC')), s.vis, s.updated_at, CAST(parseDateTime64BestEffort(JSONExtractString(s._before, 'updated_at'), 6, 'UTC') AS DateTime64(6, 'UTC'))) AS updated_at
FROM (SELECT *, true AS present, _tx_id = 0 OR _synced_at < now64(3) - INTERVAL 30 MINUTE OR _tx_id IN (SELECT tx_id FROM visible) AS vis FROM silver.product_reviews FINAL WHERE id IN (SELECT k FROM snap.dirty WHERE tbl = 'product_reviews' AND v = {v:UInt64})) AS s
FULL OUTER JOIN (
    SELECT toUUIDOrZero(JSONExtractString(if(op = 'd', before, after), 'id')) AS k, argMin(before, lsn) AS row, true AS found
    FROM bronze.cdc_events
    WHERE source_table = 'product_reviews' AND event_ts > now64(3) - INTERVAL 35 MINUTE AND tx_id != 0
      AND tx_id NOT IN (SELECT tx_id FROM visible)
    GROUP BY k HAVING k IN (SELECT k FROM snap.dirty WHERE tbl = 'product_reviews' AND v = {v:UInt64})) AS r ON s.id = r.k
WHERE if(r.found, r.row != 'null', s.present AND (s.vis OR s._before != 'null'))
SETTINGS join_use_nulls = 0;

CREATE OR REPLACE VIEW snap.changed_keys AS
SELECT DISTINCT source_table AS tbl,
       toUUIDOrZero(JSONExtractString(if(op = 'd', before, after), multiIf(source_table = 'inventory', 'sku_id', source_table = 'order_status_history', 'order_id', source_table = 'inventory_movements', 'sku_id', source_table = 'shipment_events', 'shipment_id', source_table = 'price_history', 'sku_id', source_table = 'seller_ledger_entries', 'shop_id', source_table = 'shop_wallets', 'shop_id', 'id'))) AS k
FROM bronze.cdc_events
WHERE source_table IN ('customers', 'customer_addresses', 'sellers', 'shops', 'categories', 'brands', 'products', 'product_skus', 'inventory', 'carts', 'cart_items', 'checkouts', 'orders', 'order_items', 'order_status_history', 'payments', 'refunds', 'inventory_movements', 'shipments', 'shipment_events', 'price_history', 'vouchers', 'voucher_usages', 'campaigns', 'flash_sale_items', 'returns', 'return_items', 'seller_ledger_entries', 'shop_wallets', 'seller_payouts', 'product_reviews')
  AND event_ts >= {since:DateTime64(3, 'UTC')}
  AND (tx_id IN (SELECT tx_id FROM bronze.cdc_transactions
                 WHERE ingested_at > now64(3) - INTERVAL 2 HOUR
                   AND kafka_offset >= {prev:UInt64} AND kafka_offset < {v:UInt64})
       OR (tx_id = 0 AND ingested_at >= {since:DateTime64(3, 'UTC')}));
